            "type": "string",
            "description": "天气查询对应的区县名称。",
            "sampleValue": "青浦区"
          }
        },
        "current": {
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "多云"
          },
          "airQuality": {
            "type": "string",
            "description": "当前空气质量或PM2.5展示摘要。",
            "sampleValue": "36"
          }
        },
        "daily": {
          "type": "array",
          "description": "从今天开始按日期升序排列的每日预报。",
          "sampleValue": [
            {
              "rainProbabilityPercent": "70%"
